function o(t){const e=Number(t);return!Number.isFinite(e)||e<=0?0:Math.floor(e)}function s(t,e){const r=o(e);if(r<=0)return null;const a=Number.isFinite(t)?Math.max(0,t):0;return a>=r?100:Math.round(a/r*1e3)/10}function c(t,e){const r=o(e);if(r<=0)return null;const a=Number.isFinite(t)?t:0;return a<=0?"out_of_stock":a>=r?"healthy":a/r<.5?"critical":"low_stock"}function n(t,e=!1){if(!t)return"—";if(!e)switch(t){case"healthy":return"Healthy";case"low_stock":return"Low Stock";case"critical":return"Critical";case"out_of_stock":return"Out of Stock"}switch(t){case"healthy":return"سليم";case"low_stock":return"مخزون منخفض";case"critical":return"حرج";case"out_of_stock":return"نفد المخزون"}}function u(t){switch(t){case"healthy":return"bg-emerald-500";case"low_stock":return"bg-amber-500";case"critical":return"bg-rose-500";case"out_of_stock":return"bg-rose-600";default:return"bg-slate-300"}}function l(t){switch(t){case"healthy":return"bg-emerald-50 text-emerald-700 border-emerald-200";case"low_stock":return"bg-amber-50 text-amber-800 border-amber-200";case"critical":return"bg-orange-50 text-orange-800 border-orange-200";case"out_of_stock":return"bg-rose-50 text-rose-700 border-rose-200";default:return"bg-slate-50 text-slate-600 border-slate-200"}}export{s as a,u as b,n as c,l as d,c as s};
